// The V3 skin generator's library (V3 PLAN 7.3). It reads src/skin/v3.tokens.json and returns every generated file as
// text, so build-skin.mjs can write them and test-skin-sync.mjs can compare them with the disk without writing anything.
// Deterministic: no clock, no environment, fixed key order.
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

export const ui = dirname(dirname(fileURLToPath(import.meta.url)));
export const skinDir = join(ui, "src", "skin");
const SOURCE = "skin/v3.tokens.json";
const HEADER = `GENERATED by ui/scripts/build-skin.mjs from ${SOURCE}. Do not edit: change the source and run \`npm --prefix ui run build:skin\`.`;

export function loadSource() {
  return JSON.parse(readFileSync(join(skinDir, "v3.tokens.json"), "utf8"));
}

// ---- values

/** {paper.200} -> the primitive's value. Throws on an unknown path. */
export function resolveRefs(source, value) {
  return value.replace(/\{([\w.]+)\}/g, (_, path) => {
    const hit = path.split(".").reduce((node, key) => (node && typeof node === "object" ? node[key] : undefined), source.primitives);
    if (typeof hit !== "string") throw new Error(`unknown primitive {${path}}`);
    return hit;
  });
}
const usedPrimitives = source => {
  const used = new Set();
  const scan = value => { for (const [, path] of String(value).matchAll(/\{([\w.]+)\}/g)) used.add(path); };
  for (const theme of Object.values(source.themes)) Object.values(theme).forEach(scan);
  Object.values(source.common.roles).forEach(scan);
  Object.values(source.scopes).forEach(scope => Object.values(scope.values).forEach(scan));
  return used;
};
const flatten = (node, prefix = "") => Object.entries(node).flatMap(([key, value]) => typeof value === "object" ? flatten(value, `${prefix}${key}.`) : [`${prefix}${key}`]);

/** Every L1 role with its resolved value, per theme: { light: {name: value}, dark: {...}, common: {...}, letter: {...} }. */
export function resolveSource(source) {
  const map = values => Object.fromEntries(Object.entries(values).map(([name, value]) => [name, resolveRefs(source, value)]));
  return { light: map(source.themes.light), dark: map(source.themes.dark), common: map(source.common.roles), letter: map(source.scopes.letter.values) };
}

/** The structure tokens as one flat { name: value } map, in source order. */
export function structureTokens(source) {
  return Object.fromEntries(source.common.structure.flatMap(group => Object.entries(group.tokens)));
}

/** Source consistency (PLAN 7.3): both themes define the same roles, nothing is defined twice, every reference resolves
 *  and every primitive is used, fallbacks and scopes name real roles, changes[] name real tokens. Returns problem strings. */
export function validate(source) {
  const problems = [];
  const light = Object.keys(source.themes.light), dark = Object.keys(source.themes.dark);
  for (const name of light) if (!dark.includes(name)) problems.push(`role --${name} is in light but not in dark`);
  for (const name of dark) if (!light.includes(name)) problems.push(`role --${name} is in dark but not in light`);
  const roles = new Set([...light, ...Object.keys(source.common.roles)]);
  for (const name of Object.keys(source.common.roles)) if (light.includes(name)) problems.push(`role --${name} is both themed and common`);
  const structure = Object.keys(structureTokens(source));
  const seen = new Set();
  for (const name of structure) { if (seen.has(name)) problems.push(`structure token --${name} is defined twice`); seen.add(name); if (roles.has(name)) problems.push(`--${name} is both a role and a structure token`); }
  try { resolveSource(source); } catch (error) { problems.push(error.message); }
  const used = usedPrimitives(source);
  for (const path of flatten(source.primitives)) if (!used.has(path)) problems.push(`primitive ${path} is not used`);
  for (const [group, values] of Object.entries(source.fallbacks ?? {})) for (const name of Object.keys(values)) if (!roles.has(name)) problems.push(`fallbacks.${group}: --${name} is not a role`);
  for (const [scope, { values }] of Object.entries(source.scopes)) for (const name of Object.keys(values)) if (!roles.has(name)) problems.push(`scopes.${scope}: --${name} is not a role`);
  for (const [platform, { selector, values }] of Object.entries(source.platforms ?? {}).filter(([, v]) => typeof v === "object")) {
    if (!selector.includes(`[data-desktop="${platform}"]`)) problems.push(`platforms.${platform}: the selector must name [data-desktop="${platform}"]`);
    for (const name of Object.keys(values)) if (!name.startsWith("c-")) problems.push(`platforms.${platform}: --${name} is not a component role (--c-*)`);
  }
  for (const change of source.changes) for (const name of change.names) if (!roles.has(name) && !structure.includes(name)) problems.push(`changes[]: --${name} is not a token`);
  return problems;
}

// ---- probe skins: every role gets a value that differs from the V3 one (test:skin-sensitivity)

function hexToRgb(hex) {
  let digits = hex.replace("#", "").toLowerCase();
  if (digits.length <= 4) digits = [...digits].map(c => c + c).join("");
  const n = parseInt(digits.slice(0, 6), 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}
function rgbToHsl([r, g, b]) {
  r /= 255; g /= 255; b /= 255;
  const max = Math.max(r, g, b), min = Math.min(r, g, b), l = (max + min) / 2, d = max - min;
  if (!d) return [0, 0, l];
  const s = d / (1 - Math.abs(2 * l - 1));
  const h = max === r ? ((g - b) / d) % 6 : max === g ? (b - r) / d + 2 : (r - g) / d + 4;
  return [(h * 60 + 360) % 360, s, l];
}
function hslToRgb([h, s, l]) {
  const c = (1 - Math.abs(2 * l - 1)) * s, x = c * (1 - Math.abs(((h / 60) % 2) - 1)), m = l - c / 2;
  const [r, g, b] = h < 60 ? [c, x, 0] : h < 120 ? [x, c, 0] : h < 180 ? [0, c, x] : h < 240 ? [0, x, c] : h < 300 ? [x, 0, c] : [c, 0, x];
  return [r, g, b].map(v => Math.round((v + m) * 255));
}
const hex2 = n => n.toString(16).padStart(2, "0");
export const PROBES = {
  "probe-a": { hue: 120, lightness: l => 1 - l, scale: 1.5, share: 9, tilt: 3, opacity: ".8", family: "Probe A" },
  "probe-b": { hue: 240, lightness: l => (l + 0.35) % 1, scale: 0.6, share: -7, tilt: -4, opacity: ".6", family: "Probe B" },
};
function probeColor(rgb, probe) {
  const [h, s, l] = rgbToHsl(rgb);
  return hslToRgb([(h + probe.hue) % 360, Math.min(1, s * 0.5 + 0.5), probe.lightness(l)]);
}
/** The V3 value with every colour, length, share, angle and font family changed. */
export function probeValue(value, probe) {
  const mapText = text => text
    .replace(/#[0-9a-fA-F]{3,8}\b/g, match => { const rgb = probeColor(hexToRgb(match), probe); return `#${rgb.map(hex2).join("")}`; })
    .replace(/rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*(?:,\s*([\d.]+)\s*)?\)/g, (_, r, g, b, a) => {
      const [nr, ng, nb] = probeColor([+r, +g, +b], probe);
      return a === undefined ? `rgb(${nr}, ${ng}, ${nb})` : `rgba(${nr}, ${ng}, ${nb}, ${a})`;
    })
    .replace(/(-?\d*\.?\d+)px/g, (_, n) => `${Math.round((+n * probe.scale + 1) * 100) / 100}px`)
    .replace(/(\d*\.?\d+)%/g, (_, n) => `${+n + probe.share > 100 || +n + probe.share < 0 ? +n - probe.share : +n + probe.share}%`)
    .replace(/(-?\d*\.?\d+)deg/g, (_, n) => `${+n + probe.tilt}deg`);
  if (/^url\(/.test(value)) return value.replace(/%23([0-9a-fA-F]{3,6})\b/g, (_, hex) => `%23${probeColor(hexToRgb(hex), probe).map(hex2).join("")}`).replace("%3Cpath ", `%3Cpath opacity='${probe.opacity}' `);
  if (/^["A-Za-z]/.test(value) && /(sans-serif|system-ui|monospace)/.test(value)) return `"${probe.family}", ${value}`;
  return mapText(value);
}

// ---- emitters

const cascadeOrder = () => readFileSync(join(ui, "src", "cascade.css"), "utf8").replace(/\/\*[\s\S]*?\*\//g, "").match(/@layer [^;]+;/)[0];
const declare = (values, indent = "  ") => Object.entries(values).map(([name, value]) => `${indent}--${name}: ${value};`).join("\n");
const comment = (text, indent = "") => `${indent}/* ${text.split("\n").join(`\n${indent}   `)} */`;

/** One skin sheet: light roles on the skin's root, dark roles on its dark root, the Letter scope and the fallbacks. */
export function emitSkin(source, skin, transform = value => value) {
  const resolved = resolveSource(source);
  const mapAll = values => Object.fromEntries(Object.entries(values).map(([name, value]) => [name, transform(value)]));
  const root = `:root:where([data-skin="${skin}"])`;
  const dark = `${root}[data-theme="dark"]`;
  const both = `${root},\n  ${dark}`;
  const out = [
    `/* ${HEADER} */`,
    cascadeOrder(),
    "@layer skin {",
    `${root} {`, "  color-scheme: light;", declare(mapAll(resolved.light)), declare(mapAll(resolved.common)), "}",
    `${dark} {`, "  color-scheme: dark;", declare(mapAll(resolved.dark)), "}",
    comment(source.scopes.letter.note),
    `${dark} ${source.scopes.letter.selector} {`, declare(mapAll(resolved.letter)), "}",
  ];
  if (skin === "v3") {
    const fallbacks = source.fallbacks;
    const block = values => declare(Object.fromEntries(Object.entries(values).map(([name, value]) => [name, resolveRefs(source, value)])), "    ");
    for (const [platform, { selector, values }] of Object.entries(source.platforms ?? {}).filter(([, v]) => typeof v === "object")) {
      out.push(comment(`Platform material, ${platform} (PLAN 7.4): component roles only.`), `${selector} {`, declare(values), "}");
    }
    out.push(
      comment("Without backdrop blur, glass is the strong glass. Both theme selectors, or the dark block would win."),
      "@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {", `  ${both} {`, block(fallbacks.noBackdropFilter), "  }", "}",
      comment("Reduced transparency: glass is the plain surface and the bands stop blurring."),
      "@media (prefers-reduced-transparency: reduce) {", `  ${both} {`, block(fallbacks.reducedTransparency), "  }", "}",
      comment("Forced colours: author colours give way to system colours."),
      "@media (forced-colors: active) {", `  ${both} {`, block(fallbacks.forcedColors), "  }", "}",
    );
  }
  out.push("}", "");
  return out.join("\n");
}

export function emitStructure(source) {
  const out = [
    `/* ${HEADER}`,
    "   Structure tokens: space, borders, focus, type scale, motion, layers and layout widths. Not part of a skin: every skin uses them.",
    "   Guards: test:motion-tokens (motion), test:layers (the --z-* scale), test:skin-sync (this file against the source). */",
    "@layer tokens {",
  ];
  for (const group of source.common.structure) {
    out.push(comment(group.note), ":root {", Object.entries(group.tokens).map(([name, value]) => `  --${name}:${value};`).join("\n"), "}", "");
  }
  out.pop();
  out.push("}", "");
  for (const property of source.common.properties) {
    out.push(comment(property.note), `@property ${property.name} { syntax:"${property.syntax}"; inherits:${property.inherits}; initial-value:${property.initial}; }`);
  }
  out.push("");
  return out.join("\n");
}

const camel = name => name.replace(/-(\w)/g, (_, c) => c.toUpperCase());
const MOTION_NAMES = ["instant", "press", "quick", "base", "panel-in", "panel-out", "flight", "pop-in", "pop-out"];
const EASE_NAMES = ["out", "settle", "spring", "inout", "in", "pop", "pen", "stamp"];
const ARRIVE_NAMES = { message: "m-arrive", reduced: "m-arrive-reduced" };
const MARK_NAMES = { fill: "m-mark-fill", tick: "m-mark-tick", strike: "m-mark-strike", strikeDelay: "m-mark-strike-delay", highlight: "m-mark-hl", highlightDelay: "m-mark-hl-delay", stamp: "m-mark-stamp" };
const ms = value => { const found = /^(\d+)ms$/.exec(value); if (!found) throw new Error(`not a duration: ${value}`); return Number(found[1]); };
const object = (name, entries, doc) => `${doc ? `/** ${doc} */\n` : ""}export const ${name} = {\n${entries.map(([key, value]) => `  ${key}: ${JSON.stringify(value)},`).join("\n")}\n} as const;\n`;

export function emitTokens(source) {
  const tokens = structureTokens(source);
  const get = name => { if (!(name in tokens)) throw new Error(`structure token --${name} is missing`); return tokens[name]; };
  const roles = [...Object.keys(source.themes.light), ...Object.keys(source.common.roles)];
  return [
    `// ${HEADER}`,
    "// The JS side of the skin: motion, layers and the role names. The CSS twin of each value is in skin/structure.css.",
    "",
    object("MOTION", MOTION_NAMES.map(name => [camel(name), ms(get(`m-${name}`))]), "Durations in ms (--m-*). Web Animations callers read these."),
    object("EASE", EASE_NAMES.map(name => [name, get(`ease-${name}`).replace(/\s+/g, "")]), "Easing curves (--ease-*)."),
    object("ARRIVE", Object.entries(ARRIVE_NAMES).map(([key, name]) => [key, ms(get(name))]), "How a new message arrives, in ms."),
    object("MARKS", Object.entries(MARK_NAMES).map(([key, name]) => [key, ms(get(name))]), "Pen marks, in ms: each runs once, when a state changes."),
    object("Z", Object.keys(tokens).filter(name => name.startsWith("z-")).map(name => [camel(name.slice(2)), Number(get(name))]), "The --z-* layer scale."),
    `/** The L1 role names, in the order of skin/v3.css. */\nexport const SKIN_ROLES = ${JSON.stringify(roles, null, 2)} as const;\nexport type SkinRole = (typeof SKIN_ROLES)[number];\n`,
  ].join("\n");
}

/** Every generated file: { "skin/v3.css": text, ... } with paths relative to ui/src. */
export function buildAll(source = loadSource()) {
  const problems = validate(source);
  if (problems.length) throw new Error(`skin source is inconsistent:\n  ${problems.join("\n  ")}`);
  return {
    "skin/v3.css": emitSkin(source, "v3"),
    "skin/probe-a.css": emitSkin(source, "probe-a", value => probeValue(value, PROBES["probe-a"])),
    "skin/probe-b.css": emitSkin(source, "probe-b", value => probeValue(value, PROBES["probe-b"])),
    "skin/structure.css": emitStructure(source),
    "skin/tokens.ts": emitTokens(source),
  };
}

// ---- contrast (the pairs palette.py checks; test:skin-contrast)

const luminance = hex => {
  const [r, g, b] = hexToRgb(hex).map(v => v / 255).map(v => (v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4));
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
};
export const contrast = (a, b) => { const [hi, lo] = [luminance(a), luminance(b)].sort((x, y) => y - x); return (hi + 0.05) / (lo + 0.05); };
